l":"https://illinoisinsuranceappraiser.com/appraiser-services/illinois-homeowner-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/association-commercial-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/hailstorm-roof-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado, Derecho & Wind Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/tornado-derecho-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Basement, Backup & Water Damage Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/basement-backup-water-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/fire-soot-smoke-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Frozen Pipe & Ice Dam Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/polar-vortex-freeze-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property Appraisal","url":"https://illinoisinsuranceappraiser.com/appraiser-services/household-contents-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://illinoisinsuranceappraiser.com/appraiser-services/adjuster-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://illinoisinsuranceappraiser.com/appraiser-services/impartial-umpire-appointments/"}}]},"priceRange":"$$","knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Tornado and derecho damage","Sewer backup claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://illinoisinsuranceappraiser.com/#website","url":"https://illinoisinsuranceappraiser.com/","name":"Illinois Insurance Appraiser","publisher":{"@id":"https://illinoisinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#webpage","url":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/","name":"Insurance Claim Terms Glossary | ACV, RCV, Umpire & More","description":"A searchable glossary of property insurance claim terms: actual cash value, replacement cost, appraisal award, umpire, Section 155 and more.","inLanguage":"en-US","isPartOf":{"@id":"https://illinoisinsuranceappraiser.com/#website"},"about":{"@id":"https://illinoisinsuranceappraiser.com/#business"},"publisher":{"@id":"https://illinoisinsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#primaryimage","url":"https://illinoisinsuranceappraiser.com/assets/img/photos/calculator-sticky-note.webp","width":960,"height":631},"breadcrumb":{"@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},"mainEntity":{"@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://illinoisinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms","item":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/"}],"@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for the extra cost of living elsewhere while your home is being repaired. Also called loss of use."},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It’s the only question an appraisal panel decides."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by at least two of the three panel members setting the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to value the loss in appraisal. Policies usually require appraisers to be competent and impartial."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage — the part of a homeowners policy that covers the house itself."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other-structures coverage for detached garages, fences, sheds and similar buildings."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for furniture, clothing, electronics and other belongings."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing coverages, limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The amount you pay toward a covered loss before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value of an item due to age, wear or obsolescence."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm associated with a line of fast-moving thunderstorms."},{"@type":"DefinedTerm","name":"Detach and reset","description":"Removing an item, such as a gutter or light fixture, to perform a repair and then reinstalling it."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage."},{"@type":"DefinedTerm","name":"Exclusion","description":"A policy provision that removes coverage for certain causes or types of loss."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state-mandated insurer of last resort. In Illinois, the Illinois FAIR Plan Association."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof membrane installed at eaves, valleys and other vulnerable areas of a roof."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the edge of a roof that traps meltwater, which can then back up under shingles."},{"@type":"DefinedTerm","name":"Like kind and quality","description":"The standard that replacement materials should be similar in type and quality to what was damaged."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as a quantity of shingles or a square footage of drywall."},{"@type":"DefinedTerm","name":"Matching","description":"Whether replacement materials reasonably match the undamaged materials next to them."},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping a roof or drying a basement."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of complying with building codes when repairing or rebuilding."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for managing a job, typically added when several trades are involved."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling coverage limit rather than a flat dollar amount."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which an insurer may request within a set time."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation withheld from the first payment and paid once repairs or replacement are complete."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with like kind and quality, without depreciation."},{"@type":"DefinedTerm","name":"Roofing square","description":"A unit of roof area equal to 100 square feet."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full list of damaged items and the repairs needed to restore them."},{"@type":"DefinedTerm","name":"Section 155","description":"A provision of the Illinois Insurance Code that lets courts award attorney fees and a limited penalty for vexatious and unreasonable claim delays or denials."},{"@type":"DefinedTerm","name":"Sewer backup endorsement","description":"An endorsement that adds coverage for water backing up through sewers or drains, usually with its own limit."},{"@type":"DefinedTerm","name":"Sublimit","description":"A lower limit within a policy that applies to a specific type of property or loss."},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy provision setting the time within which a lawsuit must be filed against the insurer."},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missing or underpriced in an estimate."},{"@type":"DefinedTerm","name":"Test square","description":"A 10-by-10-foot area of roof used to count and document hail impacts."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property repairs."}],"@id":"https://illinoisinsuranceappraiser.com/insurance-claim-terms/#definedtermset"}]}</script>
